function applyDaylight(){const t=world.settings.sun,angle=t*Math.PI;sun.position.set(Math.cos(angle)*65,25+Math.sin(angle)*60,35);const warmth=Math.abs(t-.5)*2;sun.color.set('#fff7df').lerp(new THREE.Color('#f6b174'),warmth*.55);sun.intensity=2.75-warmth*.7;hemi.intensity=1.05-warmth*.18;const desert=world.settings.biome==='desert',golden=t>.7||t<.3;const top=new THREE.Color(desert?'#7fb4e0':'#5ea6e6'),hor=new THREE.Color(desert?'#f0e2c4':'#d6ecf4');if(golden){top.lerp(new THREE.Color('#4f86d8'),warmth*.3);hor.lerp(new THREE.Color('#ffdcb0'),warmth*.5);}sky.material.uniforms.top.value.copy(top);sky.material.uniforms.hor.value.copy(hor);sky.material.uniforms.sunCol.value.copy(sun.color);scene.background.copy(hor);scene.fog.color.copy(hor);$('#daylightValue').textContent=t<.3?'Morning':t>.7?'Golden hour':'Midday';}
