function showHabitat(o){const def=catalogById.get(o.type);if(o.type!=='enclosure'&&def.category!=='Animals'){$('#habitat').hidden=true;return;}const enclosure=o.type==='enclosure'?o:enclosureFor(o.x,o.z);if(!enclosure){$('#habitat').hidden=false;$('#habitat').textContent='Free roaming · Place inside an enclosure to create a habitat.';return;}const residents=world.objects.filter(a=>catalogById.get(a.type)?.category==='Animals'&&enclosureFor(a.x,a.z)?.id===enclosure.id);const contents=world.objects.filter(a=>enclosureFor(a.x,a.z)?.id===enclosure.id);let hasWater=contents.some(a=>(a.type==='water-trough'||catalogById.get(a.type)?.attracts==='water'));for(let z=-4;z<=4&&!hasWater;z+=2)for(let x=-6;x<=6;x+=2){const scale=enclosure.scale||1,c=Math.cos(enclosure.rotation||0),s=Math.sin(enclosure.rotation||0);if(waterAt(enclosure.x+(x*c+z*s)*scale,enclosure.z+(-x*s+z*c)*scale)!==null)hasWater=true;}const needs=[];if(!hasWater)needs.push('needs water');if(!contents.some(a=>(a.type==='shelter'||catalogById.get(a.type)?.shelter)))needs.push('shelter missing');if(!contents.some(a=>(a.type==='food'||catalogById.get(a.type)?.attracts==='food')))needs.push('add a food station');const demand=residents.reduce((s,a)=>s+({elephant:65,giraffe:55,horse:30,deer:20}[a.type]||12),0);if(demand>160*(enclosure.scale||1)**2)needs.push('needs more space');$('#habitat').hidden=false;$('#habitat').textContent=`${residents.length} resident${residents.length!==1?'s':''} · ${needs.length?needs.join(' · '):'A welcoming habitat'}`;}
