function linePlan(start,end,path=null,close=false){if(isFenceType(selectedType))return planFence(path||[start,end],{type:selectedType,scale:Number($('#placementScale').value)||1,close,tolerance:$('#fenceMode').value==='points'?0:.35});return planLine(start,end,{type:selectedType,scale:Number($('#placementScale').value)||1,snap:$('#snap').checked,rotation});}
