function commitLine(start,end,path=null,close=false){const plan=linePlan(start,end,path,close);if(!plan.length){notify(plan.error||'Draw a longer fence, or choose at least two corners.');return;}if(world.objects.length+plan.length>3000){notify('This world supports up to 3,000 objects.');return;}const bad=plan.map(p=>placementCheck(p.type,p.x,p.z,null,p.scale,p.length)).find(c=>!c.ok);if(bad){notify(bad.message);return;}world.checkpoint();for(const p of plan){if($('#foundation').checked&&waterAt(p.x,p.z)===null&&catalogById.get(p.type).category==='Roads')levelGround(p.x,p.z,catalogById.get(p.type).radius*p.scale+.4);world.addObject({id:uid(),...p});}world.rebuildWater();rebuild();setDirty();notify(`${plan.length} connected pieces placed. Undo removes the whole row.`);}
function makePond(p){const radius=+$('#pondSize').value;if(world.objects.some(o=>isObstacle(catalogById.get(o.type))&&Math.hypot(o.x-p.x,o.z-p.z)<radius+(catalogById.get(o.type).radius||1)*(o.scale||1))){notify('Move the pond away from buildings and large decorations.');return;}const undo=[...world._undo],redo=[...world._redo];world.checkpoint();const result=world.stampPond(p.x,p.z,{radius,depth:+$('#pondDepth').value});if(!result.ok){world._undo=undo;world._redo=redo;notify(result.message);return;}rebuild();setDirty();notify('A pond, ready for fish and waterside plants.');}
