canvas.addEventListener('pointerdown',e=>{if(!projects?.ready)return;if(e.pointerType==='touch'&&activeTool!=='camera'){touches.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);if(touches.size===1){touchRollback={snapshot:world._snapshot(),undo:[...world._undo],redo:[...world._redo],dirty,corners:fenceCorners.map(p=>p.clone())};pendingTouch=e;touchEditTimer=setTimeout(()=>beginTouchEdit(e),140);return;}clearTimeout(touchEditTimer);pendingTouch=null;linePreview.visible=false;if(touchRollback?.corners)fenceCorners=touchRollback.corners;if(gesture?.sculpt&&touchRollback){world._restore(touchRollback.snapshot);world._undo=touchRollback.undo;world._redo=touchRollback.redo;dirty=touchRollback.dirty;rebuild();$('#saveStatus').textContent=dirty?'Unsaved changes':'A fresh beginning';}const a=[...touches.values()];touchCamera={distance:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2};gesture=null;return;}beginPointer(e);});
canvas.addEventListener('pointermove',e=>{if(planetMode){if(gesture?.planet){planetRig.yaw-=(e.clientX-gesture.x)*.006;planetRig.pitch=THREE.MathUtils.clamp(planetRig.pitch+(e.clientY-gesture.y)*.004,-1.2,1.2);gesture.x=e.clientX;gesture.y=e.clientY;}return;}if(touches.has(e.pointerId))touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size>=2&&touchCamera){const a=[...touches.values()],dist=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),x=(a[0].x+a[1].x)/2,y=(a[0].y+a[1].y)/2;cameraRig.distance=THREE.MathUtils.clamp(cameraRig.distance*touchCamera.distance/Math.max(10,dist),10,world.size*1.4);panCamera(x-touchCamera.x,y-touchCamera.y);touchCamera={distance:dist,x,y};return;}if(gesture?.camera){const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(gesture.pan)panCamera(dx,dy);else{cameraRig.yaw-=dx*.006;cameraRig.pitch=THREE.MathUtils.clamp(cameraRig.pitch+dy*.004,.14,1.4);}gesture.x=e.clientX;gesture.y=e.clientY;return;}const p=hitGround(e);if(p){brushPoint=p;showBrush(p);alignPreview(p);if(gesture?.line){gesture.last=p.clone();if(gesture.fence&&$('#fenceMode').value==='freehand'){if(p.distanceTo(gesture.path.at(-1))>.65)gesture.path.push(p.clone());displayLine(gesture.start,p,[...gesture.path,p]);}else displayLine(gesture.start,p);}else if(fenceCorners.length&&activeTool==='place')displayLine(fenceCorners[0],p,[...fenceCorners,p]);if(gesture?.sculpt){const prev=gesture.last||p,dist=prev.distanceTo(p),steps=Math.min(12,Math.max(1,Math.ceil(dist/Math.max(1,+$('#brushSize').value*.25))));for(let i=1;i<=steps;i++)sculptAt(prev.clone().lerp(p,i/steps),Math.min(.07,.025/steps));gesture.last=p;}}else{brushRing.visible=false;previewGroup.visible=false;}});
function endGesture(e){if(planetMode){if(gesture?.planet&&Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)<8&&e.type!=='pointercancel'){pointer.set(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2);raycaster.setFromCamera(pointer,planetCamera);const region=planetView.pick(raycaster);if(region)visitRegion(region.id);}gesture=null;return;}if(pendingTouch&&pendingTouch.pointerId===e.pointerId){clearTimeout(touchEditTimer);if(e.type!=='pointercancel')beginTouchEdit(pendingTouch);else pendingTouch=null;}if(gesture?.tap&&!touchCamera&&e.type!=='pointercancel'&&touches.size===1){beginPointer({pointerType:'mouse',pointerId:e.pointerId,clientX:e.clientX,clientY:e.clientY,button:0});}if(gesture?.line){if(e.type!=='pointercancel')commitLine(gesture.start,gesture.last,gesture.fence&&$('#fenceMode').value==='freehand'?[...gesture.path,gesture.last]:null);linePreview.visible=false;}touches.delete(e.pointerId);if(touches.size<2)touchCamera=null;if(gesture?.sculpt){const result=world.rebuildWater();buildWater();buildObjects();buildAmbient();buildGrid();drawMinimap();if(result.drained)notify('A basin opened to the edge, so its water drained.');}gesture=null;}
