addEventListener('keydown',e=>{if(!projects?.ready)return;if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();historyAction(e.shiftKey?'redo':'undo');}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}else if(e.key==='Escape'){setTool('camera');$('#worldMenu').hidden=true;}else if(e.key.toLowerCase()==='r')$('#rotate').click();else if(e.key.toLowerCase()==='q'&&!flyMode)$('#rotateBack').click();else if(['Delete','Backspace'].includes(e.key)&&activeTool==='select')$('#delete').click();else if(e.code==='Space'){e.preventDefault();setTool('camera');}else if(e.key==='1')setTool('raise');else if(e.key==='2')setTool('lower');else if(e.key==='3')setTool('smooth');else if(e.key==='4')setTool('flatten');else if(e.key==='5')setTool('paint');else if(e.key==='6')setTool('water');else if(e.key.toLowerCase()==='c')setTool('camera');else if(e.key.toLowerCase()==='v')setTool('select');else if(e.key.toLowerCase()==='b')$('[data-tool=place]').click();else if(e.key==='/'){e.preventDefault();$('#library').hidden=false;$('#search').focus();}});

const animalCategories=new Set(['Animals','Birds','Aquatic']);
const buildingGroups=new Set(['Homes','Shops','Towers','Civic','Industry','Landmarks']);
const legacyGroups={Homes:['cottage','cabin','suburban','townhouse','villa','apartment','farmhouse'],Shops:['cafe','shop'],Towers:['glass-tower','art-deco','round-tower','green-tower'],Civic:['school','hospital','fire-station','library'],Industry:['barn','greenhouse'],Landmarks:['bridge','gazebo','windmill','plaza']};
const buildingGroup=def=>def.buildingGroup||Object.keys(legacyGroups).find(group=>legacyGroups[group].includes(def.id));
const categories=['All','New additions','Buildings','Plants','Animals','Birds','Aquatic','People','Roads','Zoo','Decorations','Land animals','New buildings','Homes','Shops','Towers','Civic','Industry','Landmarks'];
function syncLibraryNavigation(){
 const creature=activeTool==='place'&&animalCategories.has(catalogById.get(selectedType)?.category);
 const build=$('[data-tool="place"]'),animalsButton=$('#animalsToggle');
 build.classList.toggle('active',activeTool==='place'&&!creature);build.setAttribute('aria-pressed',String(activeTool==='place'&&!creature));
 animalsButton.classList.toggle('active',creature);animalsButton.setAttribute('aria-pressed',String(creature));
 $$('[data-library-section]').forEach(b=>{const active=b.dataset.librarySection===category||(b.dataset.librarySection==='Buildings'&&(category==='New buildings'||buildingGroups.has(category)));b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
}
function openLibrary(section){
 if(planetMode)showPlanet(false);catalogLimit=60;category=section;selectedType=section==='Animals'?'fox':'cottage';rotation=0;
 $('#search').value='';$('#placementScale').value='1';$('#drawLine').checked=false;fenceCorners=[];
 setTool('place');$('#library').hidden=false;renderCatalog();$('#catalog').scrollTop=0;$('#library').scrollTop=0;
}
$('#animalsToggle').onclick=()=>openLibrary('Animals');
$$('[data-library-section]').forEach(b=>b.onclick=()=>openLibrary(b.dataset.librarySection));
for(const cat of categories){const b=document.createElement('button');b.textContent=cat;b.className=cat==='All'?'active':'';b.onclick=()=>{category=cat;catalogLimit=60;renderCatalog();$('#catalog').scrollTop=0;$('#library').scrollTop=0;};$('#categories').append(b);}
function renderCatalog(){
 $('#libraryTitle').textContent=category==='Buildings'?'Buildings & fences':category==='Animals'?'Animals & wildlife':category==='New additions'?'540 new miniatures':category==='New buildings'?'60 new buildings':buildingGroups.has(category)?category:'Make it yours.';
 syncLibraryNavigation();
 const q=$('#search').value.toLowerCase().trim(),words=q.split(/\s+/).filter(Boolean);
 const matches=CATALOG.filter(x=>(category==='All'||x.category===category||(category==='New buildings'&&x.category==='Buildings'&&x.collection==='world-expansion')||(category==='New additions'&&x.collection==='world-expansion')||(category==='Land animals'&&x.category==='Animals')||(buildingGroups.has(category)&&buildingGroup(x)===category)||(category==='Animals'&&animalCategories.has(x.category))||(category==='Buildings'&&(x.category==='Zoo'||['windmill','plaza'].includes(x.id))))&&(!$('#newOnly').checked||x.collection==='world-expansion')&&words.every(word=>`${x.name} ${x.category} ${x.tags} ${x.description||''}`.toLowerCase().includes(word)));
 $('#resultCount').textContent=`${matches.length} ${category==='Animals'?'animals':matches.length===1?'object':'objects'}${matches.length>catalogLimit?' · '+catalogLimit+' shown':''}`;
 $('#catalogMore').hidden=matches.length<=catalogLimit;$('#catalogMore').textContent=`Show ${Math.min(60,Math.max(0,matches.length-catalogLimit))} more`;
 $$('#categories button').forEach(b=>{const active=b.textContent===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 $('#catalog').replaceChildren();
 if(!matches.length){const empty=document.createElement('div');empty.className='empty-state';empty.textContent='Nothing here yet. Try “house”, “tree”, “animal”, or another category.';$('#catalog').append(empty);return;}
 for(const [index,def] of matches.slice(0,catalogLimit).entries()){
  const b=document.createElement('button');b.className='asset-card'+(selectedType===def.id&&activeTool==='place'?' selected':'');b.title=def.description||def.name;b.setAttribute('aria-label',`Place ${def.name}`);
  const img=document.createElement('img');img.alt=`${def.name} preview`;img.width=432;img.height=316;img.src=`./thumbnails/${def.id}.png`;img.decoding='async';img.loading=index<6?'eager':'lazy';
  const title=document.createElement('span');title.className='asset-name';title.textContent=def.name;
  const tag=document.createElement('small');tag.textContent=def.collection==='world-expansion'?`New · ${def.buildingGroup||def.category}`:def.buildingGroup||def.category;b.append(img,title,tag);
  b.onclick=()=>{selectedType=def.id;rotation=0;$('#placementScale').value='1';$('#drawLine').checked=LINE_TYPES.has(def.id);fenceCorners=[];$('#fenceMode').value='freehand';setTool(def.id==='enclosure'?'enclosure':'place');renderCatalog();if(innerWidth<760)$('#library').hidden=true;notify(`${def.name} selected. Choose a spot in the world.`);};$('#catalog').append(b);
 }
}
$('#search').addEventListener('input',()=>{catalogLimit=60;renderCatalog();});
$('#catalogMore').onclick=()=>{catalogLimit+=60;renderCatalog();};
$('#newOnly').addEventListener('change',()=>{catalogLimit=60;renderCatalog();$('#library').scrollTop=0;});
$('#libraryToggle').onclick=()=>{$('#library').hidden=!$('#library').hidden;};$('#libraryClose').onclick=()=>$('#library').hidden=true;
$('#menuToggle').onclick=()=>{$('#worldMenu').hidden=!$('#worldMenu').hidden;$('#menuToggle').setAttribute('aria-expanded',!$('#worldMenu').hidden)};
$('#tutorialClose').onclick=()=>$('#tutorial').hidden=true;$('#startBuilding').onclick=()=>{$('#tutorial').hidden=true;setTool('raise');};$('#helpToggle').onclick=()=>$('#tutorial').hidden=!$('#tutorial').hidden;
const SAVE_KEY='morrowfield.world.v1',BACKUP_KEY='morrowfield.world.backup.v1';
function saveWorld(){try{const data=world.serialize(),previous=localStorage.getItem(SAVE_KEY);if(previous){try{WorldState.deserialize(previous,validIds);localStorage.setItem(BACKUP_KEY,previous)}catch{}}localStorage.setItem(SAVE_KEY,data);dirty=false;lastSave=Date.now();$('#saveStatus').textContent='Saved on this device';notify('Your world is saved on this device.');}catch(e){notify('This browser could not save locally. Use Export world for a backup.');}}
function saveProject(){if(projects?.ready)return projects.save();notify('Project storage is still getting ready.');return Promise.resolve(null);}
$('#save').onclick=saveProject;
async function confirmAction(title,message){const dialog=$('#modal');dialog.replaceChildren();const heading=document.createElement('h2');heading.textContent=title;const body=document.createElement('p');body.textContent=message;const row=document.createElement('div');row.className='dialog-actions';const cancel=document.createElement('button');cancel.textContent='Keep building';const ok=document.createElement('button');ok.textContent='Continue';ok.className='primary';row.append(cancel,ok);dialog.append(heading,body,row);dialog.showModal();return new Promise(resolve=>{cancel.onclick=()=>{dialog.close();resolve(false)};ok.onclick=()=>{dialog.close();resolve(true)};dialog.oncancel=()=>resolve(false);});}
async function loadWorld(){if(dirty&&!await confirmAction('Open your saved world?','Unsaved changes in this meadow will be replaced. Export them first if you want a separate copy.'))return;try{const data=localStorage.getItem(SAVE_KEY);if(!data){notify('No saved world on this device yet.');return;}let recovered=false;try{world=WorldState.deserialize(data,validIds)}catch(e){const backup=localStorage.getItem(BACKUP_KEY);if(!backup)throw e;world=WorldState.deserialize(backup,validIds);recovered=true;}selectedObject=null;setTool('camera');rebuild();setQuality(world.settings.quality);dirty=false;$('#saveStatus').textContent='Saved world loaded';notify(recovered?'The latest save was invalid. Recovered your previous backup.':'Welcome back to your little world.');}catch(e){notify(`Could not load this save: ${e.message}`);}$('#worldMenu').hidden=true;}
$('#load').onclick=()=>projects?.ready?projects.show():loadWorld();
