function goalCounts(){const c={house:0,building:0,shop:0,school:0,farm:0,plant:0,animal:0,bird:0,aquatic:0,person:0,road:0,decor:0,enclosure:0,fence:0};
 for(const o of world.objects){const it=catalogById.get(o.type)||{},w=((it.tags||'')+' '+(it.name||'')).toLowerCase(),cat=it.category;
  if(cat==='Buildings'){c.building++;if(/house|home|cottage|cabin|villa|apartment|townhouse|bungalow/.test(w))c.house++;if(/shop|cafe|café|market|store|restaurant|bakery|diner/.test(w))c.shop++;if(/school/.test(w))c.school++;}
  if(/farm|barn|silo|coop|stable|granary/.test(w))c.farm++;if(cat==='Plants')c.plant++;if(cat==='Animals')c.animal++;if(cat==='Birds')c.bird++;if(cat==='Aquatic')c.aquatic++;if(cat==='People')c.person++;if(cat==='Roads')c.road++;if(it.kind==='decoration')c.decor++;if(o.type==='enclosure')c.enclosure++;if(/fence|wall|hedge/.test(w))c.fence++;}
 c.water=world.waters.length;let hi=-99;const h=world.heights;for(let i=0;i<h.length;i+=7)if(h[i]>hi)hi=h[i];c.hill=hi;c.objects=world.objects.length;c.regions=goalState.regions.length;return c;}
function renderGoals(c){const done=Object.keys(goalState.done).length;$('#goalsCount').textContent=done+'/'+GOALS.length;if($('#goalsPanel').hidden)return;c=c||goalCounts();$('#goalsSummary').textContent=done===GOALS.length?'Every goal reached. What a place!':done+' of '+GOALS.length+' reached. Progress is for the region you are in.';
 const host=$('#goalsList');host.replaceChildren();for(const [id,icon,title,desc,f,n] of GOALS){const v=Math.min(n,Math.floor(f(c))),ok=!!goalState.done[id],row=document.createElement('div');row.className='goal'+(ok?' done':'');row.innerHTML='<i>'+icon+'</i><div><b></b><small></small></div><em></em><div class="bar"><span></span></div>';row.querySelector('b').textContent=title;row.querySelector('small').textContent=desc;row.querySelector('em').textContent=ok?'Reached':v+' / '+n;row.querySelector('.bar span').style.width=(ok?100:v/n*100)+'%';host.append(row);}}
function checkGoals(){if(!world)return;if(currentRegion&&!goalState.regions.includes(currentRegion)){goalState.regions.push(currentRegion);saveGoals();}const c=goalCounts();let got=null;for(const [id,,title,,f,n] of GOALS)if(!goalState.done[id]&&f(c)>=n){goalState.done[id]=Date.now();got=title;}
 if(got){saveGoals();notify('Goal reached: '+got+'! ('+Object.keys(goalState.done).length+' of '+GOALS.length+')');try{if(window.parent!==window)window.parent.postMessage({pbx:'score',score:Object.keys(goalState.done).length},location.origin)}catch(e){}}renderGoals(c);}
